package com.ecotrack.backend.advisor; import jakarta.validation.constraints.NotBlank; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/advisor") public class AdvisorController{private final AdvisorService s;public AdvisorController(AdvisorService s){this.s=s;}private String email(){return SecurityContextHolder.getContext().getAuthentication().getName();}@GetMapping public List<Map<String,Object>> recommend(){return s.recommend(email());}public record AskRequest(@NotBlank String question){}@PostMapping("/ask") public Map<String,Object> ask(@RequestBody AskRequest r){return s.ask(email(),r.question());}}
